fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // We assume:
    // - mask.len() == a.len()
    // - values.len() > 0

    let values_len = values.len();
    let mut result = Vec::with_capacity(a.len());

    for i in 0..a.len() {
        if mask[i] {
            // Use replacement value at i % values_len
            let replacement = values[i % values_len];
            result.push(replacement);
        } else {
            // Keep original value
            result.push(a[i]);
        }
    }

    result
}